R=Path(__file__).parent;Q=R/'qa';P=['heat-curl-a','heat-curl-b','heat-split','heat-renewal'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();write=lambda p,x:p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
