 edge.append({'phase':p,'sourceSHA256':sha(R/p/'master.png'),'sourcePerimeterAlphaMax':int(a[:,:,3][perimeter].max()),'sourcePerimeterNonzeroPixels':int((a[:,:,3][perimeter]>0).sum()),'blackWhiteCompositeEvidence':colors,'visualReview':'Full source black/white and native color composites show no visible backing card, clipped effect, wash, halo or fringe.'})
